import{_ as e,a as d,o,a6 as r}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse('{"title":"Catalog Product — Detail","description":"","frontmatter":{"outline":false,"apiType":"rest","examples":[{"id":"admin-catalog-product-detail","title":"Catalog Product Detail (type-aware, all fields inlined)","description":"Single catalog product record with all detail-level fields populated. Type-specific blocks (superAttributes/variants for configurable, bundleOptions for bundle, linkedProducts for grouped, downloadableLinks/downloadableSamples for downloadable) are populated only for the matching product type; all others are null. No IRI strings — every nested array is an inline JSON object.","query":"curl -X GET \\"https://your-domain.com/api/admin/catalog/products/42\\" \\\\\\n  -H \\"Authorization: Bearer <token>\\" \\\\\\n  -H \\"Accept: application/json\\"\\n","variables":"id=42\\n","response":"{\\n  \\"id\\": 42,\\n  \\"sku\\": \\"SP-001\\",\\n  \\"name\\": \\"Classic Watch\\",\\n  \\"type\\": \\"simple\\",\\n  \\"status\\": 1,\\n  \\"price\\": \\"99.9900\\",\\n  \\"formattedPrice\\": \\"$99.99\\",\\n  \\"quantity\\": 42,\\n  \\"baseImageUrl\\": \\"http://localhost:8000/storage/product/42/image.webp\\",\\n  \\"imagesCount\\": 3,\\n  \\"categoryId\\": 5,\\n  \\"categoryName\\": \\"Accessories\\",\\n  \\"channel\\": \\"default\\",\\n  \\"locale\\": \\"en\\",\\n  \\"attributeFamilyId\\": 1,\\n  \\"attributeFamilyName\\": \\"Default\\",\\n  \\"urlKey\\": \\"classic-watch\\",\\n  \\"visibleIndividually\\": true,\\n  \\"shortDescription\\": \\"A premium timepiece.\\",\\n  \\"description\\": \\"Full HTML description.\\",\\n  \\"metaTitle\\": null,\\n  \\"metaDescription\\": null,\\n  \\"metaKeywords\\": null,\\n  \\"weight\\": 0.5,\\n  \\"taxCategoryId\\": null,\\n  \\"manageStock\\": true,\\n  \\"inStock\\": true,\\n  \\"featured\\": false,\\n  \\"new\\": true,\\n  \\"createdAt\\": \\"2026-01-12T08:15:00+00:00\\",\\n  \\"updatedAt\\": \\"2026-04-30T14:20:09+00:00\\",\\n  \\"translations\\": [\\n    {\\n      \\"locale\\": \\"en\\",\\n      \\"name\\": \\"Classic Watch\\",\\n      \\"description\\": \\"Full HTML description.\\",\\n      \\"shortDescription\\": \\"A premium timepiece.\\",\\n      \\"urlKey\\": \\"classic-watch\\",\\n      \\"metaTitle\\": null,\\n      \\"metaDescription\\": null,\\n      \\"metaKeywords\\": null\\n    }\\n  ],\\n  \\"images\\": [\\n    {\\n      \\"id\\": 1,\\n      \\"path\\": \\"product/42/img1.webp\\",\\n      \\"url\\": \\"http://localhost/storage/product/42/img1.webp\\",\\n      \\"sortOrder\\": 0\\n    }\\n  ],\\n  \\"categories\\": [\\n    {\\n      \\"id\\": 5,\\n      \\"name\\": \\"Accessories\\",\\n      \\"slug\\": \\"accessories\\"\\n    }\\n  ],\\n  \\"inventories\\": [\\n    {\\n      \\"sourceId\\": 1,\\n      \\"sourceCode\\": \\"default\\",\\n      \\"qty\\": 42\\n    }\\n  ],\\n  \\"customerGroupPrices\\": [],\\n  \\"superAttributes\\": null,\\n  \\"variants\\": null,\\n  \\"bundleOptions\\": null,\\n  \\"linkedProducts\\": null,\\n  \\"downloadableLinks\\": null,\\n  \\"downloadableSamples\\": null,\\n  \\"channels\\": [\\n    { \\"id\\": 1, \\"code\\": \\"default\\", \\"name\\": \\"Default Channel\\", \\"assigned\\": true },\\n    { \\"id\\": 2, \\"code\\": \\"mobile\\", \\"name\\": \\"Mobile Channel\\", \\"assigned\\": false }\\n  ],\\n  \\"attributes\\": [\\n    { \\"id\\": 1, \\"code\\": \\"sku\\", \\"adminName\\": \\"SKU\\", \\"type\\": \\"text\\", \\"isRequired\\": true, \\"valuePerChannel\\": false, \\"valuePerLocale\\": false, \\"groupCode\\": \\"general\\", \\"groupName\\": \\"General\\", \\"value\\": \\"SP-001\\", \\"options\\": null },\\n    { \\"id\\": 23, \\"code\\": \\"color\\", \\"adminName\\": \\"Color\\", \\"type\\": \\"select\\", \\"isRequired\\": false, \\"valuePerChannel\\": false, \\"valuePerLocale\\": false, \\"groupCode\\": \\"general\\", \\"groupName\\": \\"General\\", \\"value\\": null, \\"options\\": [ { \\"id\\": 1, \\"adminName\\": \\"Red\\", \\"swatchValue\\": \\"#ff0000\\", \\"sortOrder\\": 1 } ] },\\n    { \\"id\\": 25, \\"code\\": \\"meta_title\\", \\"adminName\\": \\"Meta Title\\", \\"type\\": \\"textarea\\", \\"isRequired\\": false, \\"valuePerChannel\\": true, \\"valuePerLocale\\": true, \\"groupCode\\": \\"meta_description\\", \\"groupName\\": \\"Meta Description\\", \\"value\\": null, \\"options\\": null }\\n  ]\\n}\\n","commonErrors":[{"error":"Not Found (404)","cause":"The product ID does not exist in the database","solution":"Verify the ID with the listing endpoint `GET /api/admin/catalog/products`"},{"error":"Unauthorized (401)","cause":"Missing, invalid, expired, or revoked admin Bearer token","solution":"Send a valid admin Bearer token (Integration token) in the Authorization header. See the Authentication page."}]}]},"headers":[],"relativePath":"api/rest-api/admin/catalog/products/products-detail.md","filePath":"api/rest-api/admin/catalog/products/products-detail.md","lastUpdated":1787725411000}'),a={name:"api/rest-api/admin/catalog/products/products-detail.md"};function n(i,t,c,s,l,h){return o(),d("div",null,t[0]||(t[0]=[r('<h1 id="catalog-product-—-detail" tabindex="-1">Catalog Product — Detail <a class="header-anchor" href="#catalog-product-—-detail" aria-label="Permalink to &quot;Catalog Product — Detail&quot;">​</a></h1><p>Returns a single catalog product by ID with <strong>all detail-level fields populated</strong>, including translations, images, categories, inventories, customer group prices, and type-specific blocks. This is the read endpoint for the admin <strong>Catalog → Products</strong> edit form.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Endpoint</th><th>Method</th><th>Authentication</th></tr></thead><tbody><tr><td><code>/api/admin/catalog/products/{id}</code></td><td>GET</td><td>Admin Bearer token</td></tr></tbody></table><p><code>{id}</code> must be a positive integer. The route carries a <code>requirements: [&#39;id&#39; =&gt; &#39;\\d+&#39;]</code> constraint — non-numeric path segments are rejected with <code>404</code> before reaching the provider. This prevents the <code>{id}</code> segment from accidentally matching sibling routes under <code>/catalog/products/</code>.</p><h2 id="path-parameter" tabindex="-1">Path Parameter <a class="header-anchor" href="#path-parameter" aria-label="Permalink to &quot;Path Parameter&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Yes</td><td>The numeric product ID</td></tr></tbody></table><h2 id="response-shape" tabindex="-1">Response Shape <a class="header-anchor" href="#response-shape" aria-label="Permalink to &quot;Response Shape&quot;">​</a></h2><p>The response is a <strong>single JSON object</strong> (not wrapped in a <code>{ data }</code> envelope) with the following top-level fields:</p><h3 id="core-fields-always-present" tabindex="-1">Core fields (always present) <a class="header-anchor" href="#core-fields-always-present" aria-label="Permalink to &quot;Core fields (always present)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Product ID</td></tr><tr><td><code>sku</code></td><td>string</td><td>Product SKU</td></tr><tr><td><code>name</code></td><td>string</td><td>Localised product name</td></tr><tr><td><code>type</code></td><td>string</td><td>Product type (<code>simple</code>, <code>configurable</code>, <code>bundle</code>, <code>grouped</code>, <code>downloadable</code>, <code>virtual</code>, <code>booking</code>)</td></tr><tr><td><code>status</code></td><td>integer</td><td><code>1</code> = enabled, <code>0</code> = disabled</td></tr><tr><td><code>price</code></td><td>string</td><td>Raw decimal price string (e.g. <code>&quot;99.9900&quot;</code>)</td></tr><tr><td><code>formattedPrice</code></td><td>string</td><td>Currency-formatted price (e.g. <code>&quot;$99.99&quot;</code>)</td></tr><tr><td><code>quantity</code></td><td>integer</td><td>Total quantity across all inventory sources</td></tr><tr><td><code>baseImageUrl</code></td><td>string|null</td><td>URL of the base/primary image</td></tr><tr><td><code>imagesCount</code></td><td>integer</td><td>Total number of product images</td></tr><tr><td><code>categoryId</code></td><td>integer|null</td><td>Primary category ID</td></tr><tr><td><code>categoryName</code></td><td>string|null</td><td>Primary category display name</td></tr><tr><td><code>channel</code></td><td>string</td><td>Channel code used for value resolution</td></tr><tr><td><code>locale</code></td><td>string</td><td>Locale code used for value resolution</td></tr><tr><td><code>attributeFamilyId</code></td><td>integer</td><td>Attribute family ID</td></tr><tr><td><code>attributeFamilyName</code></td><td>string</td><td>Attribute family display name</td></tr><tr><td><code>urlKey</code></td><td>string</td><td>URL slug (e.g. <code>classic-watch</code>)</td></tr><tr><td><code>visibleIndividually</code></td><td>boolean</td><td>Whether the product appears in listings</td></tr><tr><td><code>shortDescription</code></td><td>string|null</td><td>Short description (may contain HTML)</td></tr><tr><td><code>description</code></td><td>string|null</td><td>Full description (may contain HTML)</td></tr><tr><td><code>metaTitle</code></td><td>string|null</td><td>SEO meta title</td></tr><tr><td><code>metaDescription</code></td><td>string|null</td><td>SEO meta description</td></tr><tr><td><code>metaKeywords</code></td><td>string|null</td><td>SEO meta keywords</td></tr><tr><td><code>weight</code></td><td>float|null</td><td>Product weight</td></tr><tr><td><code>taxCategoryId</code></td><td>integer|null</td><td>Tax category ID</td></tr><tr><td><code>manageStock</code></td><td>boolean|null</td><td>Whether inventory is managed</td></tr><tr><td><code>inStock</code></td><td>boolean</td><td>Whether the product is currently in stock</td></tr><tr><td><code>featured</code></td><td>boolean</td><td>Whether the product is featured</td></tr><tr><td><code>new</code></td><td>boolean</td><td>Whether the product is marked as new</td></tr><tr><td><code>createdAt</code></td><td>string</td><td>ISO 8601 creation timestamp</td></tr><tr><td><code>updatedAt</code></td><td>string</td><td>ISO 8601 last-updated timestamp</td></tr></tbody></table><h3 id="translations-array" tabindex="-1"><code>translations[]</code> array <a class="header-anchor" href="#translations-array" aria-label="Permalink to &quot;`translations[]` array&quot;">​</a></h3><p>Each element is one per-locale translation row:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>locale</code></td><td>string</td><td>Locale code (e.g. <code>en</code>, <code>fr</code>)</td></tr><tr><td><code>name</code></td><td>string|null</td><td>Translated product name</td></tr><tr><td><code>description</code></td><td>string|null</td><td>Translated full description</td></tr><tr><td><code>shortDescription</code></td><td>string|null</td><td>Translated short description</td></tr><tr><td><code>urlKey</code></td><td>string|null</td><td>Translated URL slug</td></tr><tr><td><code>metaTitle</code></td><td>string|null</td><td>Translated SEO meta title</td></tr><tr><td><code>metaDescription</code></td><td>string|null</td><td>Translated SEO meta description</td></tr><tr><td><code>metaKeywords</code></td><td>string|null</td><td>Translated SEO meta keywords</td></tr></tbody></table><h3 id="images-array" tabindex="-1"><code>images[]</code> array <a class="header-anchor" href="#images-array" aria-label="Permalink to &quot;`images[]` array&quot;">​</a></h3><p>Each element is one product image:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Image ID</td></tr><tr><td><code>path</code></td><td>string</td><td>Storage path relative to the disk root</td></tr><tr><td><code>url</code></td><td>string</td><td>Full public URL</td></tr><tr><td><code>sortOrder</code></td><td>integer</td><td>Display order position</td></tr></tbody></table><h3 id="categories-array" tabindex="-1"><code>categories[]</code> array <a class="header-anchor" href="#categories-array" aria-label="Permalink to &quot;`categories[]` array&quot;">​</a></h3><p>Each element is a category the product belongs to:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Category ID</td></tr><tr><td><code>name</code></td><td>string</td><td>Category display name</td></tr><tr><td><code>slug</code></td><td>string</td><td>Category URL slug</td></tr></tbody></table><h3 id="inventories-array" tabindex="-1"><code>inventories[]</code> array <a class="header-anchor" href="#inventories-array" aria-label="Permalink to &quot;`inventories[]` array&quot;">​</a></h3><p>Each element is one inventory source row:</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>sourceId</code></td><td>integer</td><td>Inventory source ID</td></tr><tr><td><code>sourceCode</code></td><td>string</td><td>Inventory source code (e.g. <code>default</code>)</td></tr><tr><td><code>qty</code></td><td>integer</td><td>Quantity at this source</td></tr></tbody></table><h3 id="customergroupprices-array" tabindex="-1"><code>customerGroupPrices[]</code> array <a class="header-anchor" href="#customergroupprices-array" aria-label="Permalink to &quot;`customerGroupPrices[]` array&quot;">​</a></h3><p>Each element is a customer-group price override. Empty array (<code>[]</code>) when none are configured.</p><h3 id="type-specific-blocks" tabindex="-1">Type-Specific Blocks <a class="header-anchor" href="#type-specific-blocks" aria-label="Permalink to &quot;Type-Specific Blocks&quot;">​</a></h3><p>These seven fields are always present in the response but are <code>null</code> unless the product&#39;s <code>type</code> matches:</p><table tabindex="0"><thead><tr><th>Field</th><th>Present for type</th><th>Description</th></tr></thead><tbody><tr><td><code>superAttributes</code></td><td><code>configurable</code></td><td>The configurable attributes, each with its full <code>options</code> list</td></tr><tr><td><code>variants</code></td><td><code>configurable</code></td><td>Variant child products with their chosen attribute values</td></tr><tr><td><code>bundleOptions</code></td><td><code>bundle</code></td><td>Bundle option groups with their selectable products</td></tr><tr><td><code>linkedProducts</code></td><td><code>grouped</code></td><td>The associated products</td></tr><tr><td><code>downloadableLinks</code></td><td><code>downloadable</code></td><td>Download link rows — title, type, url or file, price, download limit</td></tr><tr><td><code>downloadableSamples</code></td><td><code>downloadable</code></td><td>Sample download rows</td></tr><tr><td><code>bookingProduct</code></td><td><code>booking</code></td><td>Booking sub-type, location, availability window, and slots or tickets</td></tr></tbody></table><p>Switch on <code>type</code> to know which to read. A <code>simple</code> or <code>virtual</code> product has all seven as <code>null</code>.</p><h3 id="channels-array" tabindex="-1"><code>channels[]</code> array <a class="header-anchor" href="#channels-array" aria-label="Permalink to &quot;`channels[]` array&quot;">​</a></h3><p><strong>Every</strong> channel in the store, each flagged with whether this product is assigned to it — mirrors the Channels checkbox box on the edit screen (all options shown, the product&#39;s ones ticked). The singular <code>channel</code> field above is the channel code the data was resolved for.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Channel ID</td></tr><tr><td><code>code</code></td><td>string</td><td>Channel code</td></tr><tr><td><code>name</code></td><td>string</td><td>Channel display name</td></tr><tr><td><code>assigned</code></td><td>boolean</td><td><code>true</code> if this product is assigned to the channel</td></tr></tbody></table><h3 id="attributes-array" tabindex="-1"><code>attributes[]</code> array <a class="header-anchor" href="#attributes-array" aria-label="Permalink to &quot;`attributes[]` array&quot;">​</a></h3><p>The product&#39;s <strong>attribute-family field set</strong> — the same fields the admin edit screen renders, in the same order, driven by the product&#39;s attribute family. This includes family-specific fields (e.g. <code>color</code>, <code>size</code>, <code>brand</code>, <code>product_number</code>) that aren&#39;t top-level columns. Fields with no value are still present, with <code>value: null</code>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Attribute ID</td></tr><tr><td><code>code</code></td><td>string</td><td>Attribute code (e.g. <code>sku</code>, <code>color</code>, <code>meta_title</code>)</td></tr><tr><td><code>adminName</code></td><td>string</td><td>Field label as shown in the admin</td></tr><tr><td><code>type</code></td><td>string</td><td>Input type (<code>text</code>, <code>textarea</code>, <code>price</code>, <code>boolean</code>, <code>select</code>, <code>multiselect</code>, <code>checkbox</code>, <code>date</code>, <code>datetime</code>, <code>image</code>, <code>file</code>)</td></tr><tr><td><code>isRequired</code></td><td>boolean</td><td>Whether the field is required</td></tr><tr><td><code>valuePerChannel</code></td><td>boolean</td><td>Whether the value can differ per channel</td></tr><tr><td><code>valuePerLocale</code></td><td>boolean</td><td>Whether the value can differ per locale</td></tr><tr><td><code>groupCode</code></td><td>string</td><td>Code of the field group it belongs to</td></tr><tr><td><code>groupName</code></td><td>string</td><td>Display name of the field group</td></tr><tr><td><code>value</code></td><td>mixed|null</td><td>The product&#39;s resolved value for the requested channel/locale (<code>null</code> when unset). For <code>select</code> it&#39;s the chosen option ID; for <code>multiselect</code>/<code>checkbox</code> a comma-separated list of option IDs</td></tr><tr><td><code>options</code></td><td>array|null</td><td>For <code>select</code>/<code>multiselect</code>/<code>checkbox</code>: the selectable options (<code>id</code>, <code>adminName</code>, <code>swatchValue</code>, <code>sortOrder</code>). <code>null</code> for other types</td></tr></tbody></table><h3 id="everything-arrives-inline" tabindex="-1">Everything Arrives Inline <a class="header-anchor" href="#everything-arrives-inline" aria-label="Permalink to &quot;Everything Arrives Inline&quot;">​</a></h3><p>Every nested field — <code>translations</code>, <code>images</code>, <code>videos</code>, <code>categories</code>, <code>inventories</code>, <code>customerGroupPrices</code>, <code>channels</code>, <code>attributes</code>, and all the type-specific blocks — is a plain inline JSON array. There are no IRI strings and no sub-resource links, so one call returns the whole product.</p><p><code>attributes</code> plus <code>channels</code> together reconstruct the admin edit form: <code>channels</code> renders the channel checkboxes with the assigned ones ticked, and <code>attributes</code> renders every General / Description / Meta / Settings / Price field for the product&#39;s family. The top-level convenience fields (<code>sku</code>, <code>status</code>, <code>urlKey</code>, …) also appear inside <code>attributes</code> — the same values surfaced twice, which is deliberate.</p><h3 id="where-this-differs-from-graphql" tabindex="-1">Where This Differs From GraphQL <a class="header-anchor" href="#where-this-differs-from-graphql" aria-label="Permalink to &quot;Where This Differs From GraphQL&quot;">​</a></h3><p><code>adminCatalogProduct</code> returns the same product with nested blocks as Relay connections rather than arrays, and the two are not shape-compatible:</p><ul><li><strong><code>variants[].attributeValues</code> is a map here</strong> — <code>{&quot;select_age_group&quot;: &quot;5-7 Y&quot;}</code> — but a connection of <code>{ code, adminName, value }</code> nodes over GraphQL.</li><li><strong><code>channels</code> lists every channel with an <code>assigned</code> flag here</strong>, while GraphQL returns only the assigned ones.</li><li><strong><code>attributes</code>, <code>bookingProduct</code>, and <code>warnings</code> exist only on this endpoint.</strong> They are declared in the GraphQL schema but always resolve <code>null</code> there.</li><li><strong>Scalar types differ.</strong> <code>status</code>, <code>quantity</code>, <code>weight</code>, <code>featured</code>, and <code>new</code> are real JSON numbers and booleans here; over GraphQL they are strings, with <code>&quot;&quot;</code> standing in for false.</li></ul><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>HTTP Status</th><th>Body</th></tr></thead><tbody><tr><td><code>401</code></td><td><code>{&quot;message&quot;: &quot;Unauthenticated.&quot;, &quot;error&quot;: &quot;unauthenticated&quot;}</code></td></tr><tr><td><code>404</code></td><td><code>{&quot;type&quot;: &quot;/errors/404&quot;, &quot;title&quot;: &quot;Not Found&quot;, &quot;status&quot;: 404, &quot;detail&quot;: &quot;Product not found.&quot;}</code></td></tr></tbody></table><p>A non-numeric <code>{id}</code> also returns <code>404</code>. The route constrains the segment to digits, so <code>/catalog/products/abc</code> is rejected before the product is looked up — which is what keeps the segment from swallowing sibling routes such as <code>/catalog/products/mass-delete</code>.</p><h2 id="working-with-this-endpoint" tabindex="-1">Working With This Endpoint <a class="header-anchor" href="#working-with-this-endpoint" aria-label="Permalink to &quot;Working With This Endpoint&quot;">​</a></h2><ul><li><strong>Null fields are returned, not omitted.</strong> Every one of the 55 keys is present on every response, so a key-existence check tells you nothing — test the value.</li><li><strong>The response is a bare object</strong>, unlike the listing, which wraps rows in <code>{ data, meta }</code>.</li><li><strong>Booking products are fully readable here</strong> even though they cannot be added to an admin draft cart. The cart blocks them at add-item time with HTTP <code>400</code>; reading them is unrestricted.</li></ul>',46)]))}const g=e(a,[["render",n]]);export{p as __pageData,g as default};
